-- 004 - World recovery points (Points RETRUV) — 1 commissariat + 1 universite + 1 gare par pays
-- Idempotent via IF NOT EXISTS on name — safe to re-run, skips existing rows
-- Generated from src/lib/world-recovery-points.ts — do not edit by hand

CREATE OR REPLACE FUNCTION insert_recovery_point_world(
  p_name text, p_type text, p_address text, p_city text, p_country text,
  p_lat real, p_lng real, p_phone text, p_email text, p_hours text, p_manager text
) RETURNS void AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM recovery_points WHERE name = p_name) THEN
    INSERT INTO recovery_points (name, type, address, city, country, latitude, longitude, phone, email, hours, manager_name, is_active)
    VALUES (p_name, p_type, p_address, p_city, p_country, p_lat, p_lng, p_phone, p_email, p_hours, p_manager, true);
  END IF;
END;
$$ LANGUAGE plpgsql;

